#!/usr/bin/env python3
"""Apply P0-4 Meta provider-state uncertainty hardening.

The patch is intentionally narrow: it changes only Campaign AI's approved Meta
write path and adds focused tests.  It does not change recommendation policy,
P0-3 data-quality rules, provider credentials, or Snapchat execution.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MONITOR = ROOT / "backend" / "campaign_ai_monitor_legacy.py"
TEST = ROOT / "backend" / "tests" / "test_campaign_ai_meta_provider_uncertainty_p0_4.py"

INSERT_ANCHOR = '''async def _execute_meta_approval(\n'''
HELPERS = '''def _meta_state_matches_mutation(\n    mutation: dict[str, Any],\n    state: dict[str, Any] | None,\n) -> bool:\n    \"\"\"Return True only when a provider read proves the requested mutation.\"\"\"\n    current = state if isinstance(state, dict) else {}\n    if \"status\" in mutation:\n        expected = str(mutation.get(\"status\") or \"\").upper()\n        actual = str(\n            current.get(\"status\") or current.get(\"effective_status\") or \"\"\n        ).upper()\n        return bool(expected) and actual == expected\n    if \"daily_budget\" in mutation:\n        expected_budget = str(mutation.get(\"daily_budget\") or \"\")\n        actual_budget = str(current.get(\"daily_budget\") or \"\")\n        return bool(expected_budget) and actual_budget == expected_budget\n    return False\n\n\nasync def _reconcile_meta_provider_uncertainty(\n    db: Any,\n    user_id: str,\n    entity_id: str,\n    current_state: dict[str, Any],\n) -> dict[str, Any] | None:\n    \"\"\"Resolve a prior ambiguous Meta write only from provider evidence.\n\n    A previous accepted/possibly-reached write is never retried merely because\n    its verification failed.  If the provider now proves the requested state,\n    the old execution is closed as completed.  Otherwise the entity stays\n    fail-closed and a new financial mutation is blocked.\n    \"\"\"\n    unresolved = await db[EXECUTION_COLLECTION].find_one(\n        {\n            \"user_id\": user_id,\n            \"provider\": \"meta\",\n            \"status\": {\"$in\": [\"provider_state_uncertain\", \"verification_required\"]},\n            \"$or\": [\n                {\"entity_id\": entity_id},\n                {\"result.entity_id\": entity_id},\n            ],\n        },\n        {\"_id\": 0},\n        sort=[(\"finished_at\", -1), (\"approved_at\", -1)],\n    )\n    if not unresolved:\n        return None\n    result = unresolved.get(\"result\") or {}\n    requested_change = result.get(\"requested_change\") or {}\n    if _meta_state_matches_mutation(requested_change, current_state):\n        reconciled_at = _iso()\n        execution_id = str(unresolved.get(\"execution_id\") or \"\")\n        await db[EXECUTION_COLLECTION].update_one(\n            {\"execution_id\": execution_id},\n            {\"$set\": {\n                \"status\": \"completed\",\n                \"finished_at\": reconciled_at,\n                \"result.status\": \"completed\",\n                \"result.reconciliation\": {\n                    \"status\": \"provider_state_confirmed\",\n                    \"reconciled_at\": reconciled_at,\n                    \"provider_state\": {\n                        key: current_state.get(key)\n                        for key in (\"status\", \"effective_status\", \"daily_budget\")\n                    },\n                },\n            }},\n        )\n        snapshot_id = str(unresolved.get(\"snapshot_id\") or \"\")\n        recommendation_id = str(unresolved.get(\"recommendation_id\") or \"\")\n        if snapshot_id and recommendation_id:\n            await db[RECOMMENDATION_COLLECTION].update_one(\n                {\"user_id\": user_id, \"snapshot_id\": snapshot_id},\n                {\"$set\": {\n                    \"recommendations.$[item].execution_status\": \"completed\",\n                    \"recommendations.$[item].executed_at\": reconciled_at,\n                }},\n                array_filters=[{\"item.recommendation_id\": recommendation_id}],\n            )\n        return {\n            \"resolved\": True,\n            \"execution_id\": execution_id,\n            \"status\": \"completed\",\n        }\n    raise HTTPException(\n        status_code=409,\n        detail={\n            \"code\": \"meta_provider_state_uncertain\",\n            \"execution_id\": unresolved.get(\"execution_id\"),\n            \"entity_id\": entity_id,\n            \"requested_change\": requested_change,\n            \"message\": \"Provider state must be reconciled before another Meta write.\",\n        },\n    )\n\n\n'''

OLD_META = '''async def _execute_meta_approval(\n    db: Any,\n    user_id: str,\n    recommendation: dict[str, Any],\n    target: dict[str, Any],\n    *,\n    snapshot_id: str,\n    recommendation_id: str,\n    snapshot_digest: str,\n) -> dict[str, Any]:\n    # Revalidate analytical quality first.  The provider read, state/budget\n    # comparison and POST below then remain adjacent with no intervening DB\n    # await that could widen the provider-state TOCTOU window.\n    await _execution_quality.preflight_approved_execution(\n        db,\n        recommendation_collection=RECOMMENDATION_COLLECTION,\n        user_id=user_id,\n        snapshot_id=snapshot_id,\n        recommendation_id=recommendation_id,\n        expected_digest=snapshot_digest,\n    )\n    access_token = await _meta_credential(db, user_id, _utcnow())\n    entity_id = _text(target.get(\"entity_id\"), limit=120)\n    proof = meta_appsecret_proof(access_token)\n    base = meta_graph_base()\n    async with httpx.AsyncClient(timeout=35.0) as client:\n        read = await client.get(\n            f\"{base}/{entity_id}\",\n            params={\n                \"access_token\": access_token,\n                \"appsecret_proof\": proof,\n                \"fields\": \"id,name,status,effective_status,daily_budget\",\n            },\n        )\n        if read.status_code >= 400:\n            raise HTTPException(status_code=502, detail={\"code\": \"meta_recommendation_preflight_failed\"})\n        before = read.json()\n        _execution_quality.require_provider_state_unchanged(\n            \"meta\", recommendation, target, before\n        )\n        requested = recommendation[\"action\"]\n        current_status = str(before.get(\"status\") or before.get(\"effective_status\") or \"\").upper()\n        if current_status not in {\"ACTIVE\", \"ENABLED\"}:\n            raise HTTPException(status_code=409, detail={\"code\": \"recommendation_target_no_longer_active\"})\n        if requested == \"pause\":\n            mutation = {\"status\": \"PAUSED\"}\n        else:\n            if recommendation.get(\"entity_level\") == \"ad\":\n                raise HTTPException(status_code=409, detail={\"code\": \"meta_ad_budget_change_unsupported\"})\n            current_budget = _number(before.get(\"daily_budget\"))\n            if current_budget is None or current_budget <= 0:\n                raise HTTPException(status_code=409, detail={\"code\": \"recommendation_budget_not_available\"})\n            direction = -1 if requested == \"reduce\" else 1\n            percent = min(30, max(5, int(recommendation.get(\"change_percent\") or 15)))\n            ratio = 1 + direction * percent / 100\n            mutation = {\"daily_budget\": str(max(1, int(round(current_budget * ratio))))}\n        write = await client.post(\n            f\"{base}/{entity_id}\",\n            data={\"access_token\": access_token, \"appsecret_proof\": proof, **mutation},\n        )\n        if write.status_code >= 400:\n            raise HTTPException(status_code=502, detail={\"code\": \"meta_recommendation_write_failed\"})\n        verify = await client.get(\n            f\"{base}/{entity_id}\",\n            params={\n                \"access_token\": access_token,\n                \"appsecret_proof\": proof,\n                \"fields\": \"id,name,status,effective_status,daily_budget\",\n            },\n        )\n        after = verify.json() if verify.status_code < 400 else {}\n        if \"status\" in mutation:\n            verified = str(after.get(\"status\") or after.get(\"effective_status\") or \"\").upper() == \"PAUSED\"\n        else:\n            verified = str(after.get(\"daily_budget\") or \"\") == str(mutation[\"daily_budget\"])\n        return {\n            \"provider\": \"meta\",\n            \"entity_id\": entity_id,\n            \"status\": \"completed\" if verified else \"verification_required\",\n            \"before\": {key: before.get(key) for key in (\"status\", \"effective_status\", \"daily_budget\")},\n            \"requested_change\": mutation,\n            \"verification\": after if verify.status_code < 400 else None,\n            \"provider_write_reached\": True,\n        }\n'''

NEW_META = '''async def _execute_meta_approval(\n    db: Any,\n    user_id: str,\n    recommendation: dict[str, Any],\n    target: dict[str, Any],\n    *,\n    snapshot_id: str,\n    recommendation_id: str,\n    snapshot_digest: str,\n) -> dict[str, Any]:\n    # Revalidate analytical quality first.  No provider mutation may proceed\n    # unless the P0-3 quality contract and the current provider state both hold.\n    await _execution_quality.preflight_approved_execution(\n        db,\n        recommendation_collection=RECOMMENDATION_COLLECTION,\n        user_id=user_id,\n        snapshot_id=snapshot_id,\n        recommendation_id=recommendation_id,\n        expected_digest=snapshot_digest,\n    )\n    access_token = await _meta_credential(db, user_id, _utcnow())\n    entity_id = _text(target.get(\"entity_id\"), limit=120)\n    proof = meta_appsecret_proof(access_token)\n    base = meta_graph_base()\n    async with httpx.AsyncClient(timeout=35.0) as client:\n        read = await client.get(\n            f\"{base}/{entity_id}\",\n            params={\n                \"access_token\": access_token,\n                \"appsecret_proof\": proof,\n                \"fields\": \"id,name,status,effective_status,daily_budget\",\n            },\n        )\n        if read.status_code >= 400:\n            raise HTTPException(status_code=502, detail={\"code\": \"meta_recommendation_preflight_failed\"})\n        before = read.json()\n        # P0-4: before any new financial write, reconcile an older ambiguous\n        # write from provider truth.  If it is still not provable, fail closed.\n        await _reconcile_meta_provider_uncertainty(db, user_id, entity_id, before)\n        _execution_quality.require_provider_state_unchanged(\n            \"meta\", recommendation, target, before\n        )\n        requested = recommendation[\"action\"]\n        current_status = str(before.get(\"status\") or before.get(\"effective_status\") or \"\").upper()\n        if current_status not in {\"ACTIVE\", \"ENABLED\"}:\n            raise HTTPException(status_code=409, detail={\"code\": \"recommendation_target_no_longer_active\"})\n        if requested == \"pause\":\n            mutation = {\"status\": \"PAUSED\"}\n        else:\n            if recommendation.get(\"entity_level\") == \"ad\":\n                raise HTTPException(status_code=409, detail={\"code\": \"meta_ad_budget_change_unsupported\"})\n            current_budget = _number(before.get(\"daily_budget\"))\n            if current_budget is None or current_budget <= 0:\n                raise HTTPException(status_code=409, detail={\"code\": \"recommendation_budget_not_available\"})\n            direction = -1 if requested == \"reduce\" else 1\n            percent = min(30, max(5, int(recommendation.get(\"change_percent\") or 15)))\n            ratio = 1 + direction * percent / 100\n            mutation = {\"daily_budget\": str(max(1, int(round(current_budget * ratio))))}\n        before_compact = {\n            key: before.get(key) for key in (\"status\", \"effective_status\", \"daily_budget\")\n        }\n        try:\n            write = await client.post(\n                f\"{base}/{entity_id}\",\n                data={\"access_token\": access_token, \"appsecret_proof\": proof, **mutation},\n            )\n        except Exception as exc:\n            # A transport exception does not prove that Meta did not receive the\n            # POST.  Treat it as ambiguous and never retry the mutation blindly.\n            return {\n                \"provider\": \"meta\",\n                \"entity_id\": entity_id,\n                \"status\": \"provider_state_uncertain\",\n                \"before\": before_compact,\n                \"requested_change\": mutation,\n                \"verification\": None,\n                \"provider_write_reached\": None,\n                \"uncertainty_reason\": \"meta_write_transport_outcome_unknown\",\n                \"transport_error\": type(exc).__name__,\n            }\n        if write.status_code >= 400:\n            raise HTTPException(status_code=502, detail={\"code\": \"meta_recommendation_write_failed\"})\n        try:\n            verify = await client.get(\n                f\"{base}/{entity_id}\",\n                params={\n                    \"access_token\": access_token,\n                    \"appsecret_proof\": proof,\n                    \"fields\": \"id,name,status,effective_status,daily_budget\",\n                },\n            )\n            after = verify.json() if verify.status_code < 400 else {}\n            verification_error = None\n            if verify.status_code >= 400:\n                verification_error = f\"http_{verify.status_code}\"\n        except Exception as exc:\n            after = {}\n            verification_error = type(exc).__name__\n        verified = _meta_state_matches_mutation(mutation, after)\n        return {\n            \"provider\": \"meta\",\n            \"entity_id\": entity_id,\n            \"status\": \"completed\" if verified else \"provider_state_uncertain\",\n            \"before\": before_compact,\n            \"requested_change\": mutation,\n            \"verification\": after if after else None,\n            \"provider_write_reached\": True,\n            \"uncertainty_reason\": (\n                None if verified else\n                (\"meta_verification_read_failed\" if verification_error else \"meta_verification_mismatch\")\n            ),\n            \"verification_error\": verification_error,\n        }\n'''

STARTED_OLD = '''            \"provider\": recommendation.get(\"provider\"),\n            \"action\": recommendation.get(\"action\"),\n            \"status\": \"executing\",\n'''
STARTED_NEW = '''            \"provider\": recommendation.get(\"provider\"),\n            \"entity_id\": _text(target.get(\"entity_id\"), limit=120),\n            \"entity_level\": recommendation.get(\"entity_level\"),\n            \"action\": recommendation.get(\"action\"),\n            \"status\": \"executing\",\n'''

FINAL_OLD = '''                final_status = \"completed\" if result.get(\"status\") == \"completed\" else \"verification_required\"\n                await db[EXECUTION_COLLECTION].update_one(\n                    {\"execution_id\": execution_id},\n                    {\"$set\": {\n                        \"status\": final_status,\n                        \"finished_at\": _iso(),\n                        \"writes_performed\": True,\n                        \"result\": result,\n                    }},\n                )\n'''
FINAL_NEW = '''                result_status = str(result.get(\"status\") or \"\")\n                final_status = (\n                    result_status\n                    if result_status in {\"completed\", \"provider_state_uncertain\", \"verification_required\"}\n                    else \"verification_required\"\n                )\n                await db[EXECUTION_COLLECTION].update_one(\n                    {\"execution_id\": execution_id},\n                    {\"$set\": {\n                        \"status\": final_status,\n                        \"finished_at\": _iso(),\n                        \"writes_performed\": result.get(\"provider_write_reached\") is True,\n                        \"provider_write_outcome_known\": result.get(\"provider_write_reached\") is not None,\n                        \"result\": result,\n                    }},\n                )\n'''

TEST_CONTENT = '''import pytest\nfrom fastapi import HTTPException\n\nimport campaign_ai_monitor_legacy as legacy\n\n\ndef test_p0_4_meta_state_match_is_exact_and_fail_closed():\n    assert legacy._meta_state_matches_mutation({\"status\": \"PAUSED\"}, {\"status\": \"PAUSED\"}) is True\n    assert legacy._meta_state_matches_mutation({\"status\": \"PAUSED\"}, {\"effective_status\": \"ACTIVE\"}) is False\n    assert legacy._meta_state_matches_mutation({\"daily_budget\": \"12500\"}, {\"daily_budget\": \"12500\"}) is True\n    assert legacy._meta_state_matches_mutation({\"daily_budget\": \"12500\"}, {\"daily_budget\": \"12499\"}) is False\n    assert legacy._meta_state_matches_mutation({}, {}) is False\n\n\nclass _Response:\n    def __init__(self, status_code, payload):\n        self.status_code = status_code\n        self._payload = payload\n\n    def json(self):\n        if isinstance(self._payload, Exception):\n            raise self._payload\n        return self._payload\n\n\nclass _Client:\n    def __init__(self, gets, post):\n        self.gets = list(gets)\n        self.post_response = post\n        self.posts = 0\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *args):\n        return False\n\n    async def get(self, *args, **kwargs):\n        return self.gets.pop(0)\n\n    async def post(self, *args, **kwargs):\n        self.posts += 1\n        if isinstance(self.post_response, Exception):\n            raise self.post_response\n        return self.post_response\n\n\nasync def _prepare_meta_test(monkeypatch, client):\n    async def preflight(*args, **kwargs):\n        return {}\n    async def credential(*args, **kwargs):\n        return \"token\"\n    async def reconcile(*args, **kwargs):\n        return None\n    monkeypatch.setattr(legacy._execution_quality, \"preflight_approved_execution\", preflight)\n    monkeypatch.setattr(legacy._execution_quality, \"require_provider_state_unchanged\", lambda *a, **k: None)\n    monkeypatch.setattr(legacy, \"_meta_credential\", credential)\n    monkeypatch.setattr(legacy, \"meta_appsecret_proof\", lambda token: \"proof\")\n    monkeypatch.setattr(legacy, \"meta_graph_base\", lambda: \"https://graph.test\")\n    monkeypatch.setattr(legacy, \"_reconcile_meta_provider_uncertainty\", reconcile)\n    monkeypatch.setattr(legacy.httpx, \"AsyncClient\", lambda **kwargs: client)\n\n\n@pytest.mark.asyncio\nasync def test_p0_4_successful_post_failed_verify_is_provider_state_uncertain(monkeypatch):\n    client = _Client(\n        gets=[_Response(200, {\"status\": \"ACTIVE\", \"daily_budget\": \"10000\"}), _Response(503, {})],\n        post=_Response(200, {\"success\": True}),\n    )\n    await _prepare_meta_test(monkeypatch, client)\n    result = await legacy._execute_meta_approval(\n        object(), \"u1\",\n        {\"action\": \"scale\", \"entity_level\": \"campaign\", \"change_percent\": 10},\n        {\"entity_id\": \"c1\"},\n        snapshot_id=\"s1\", recommendation_id=\"r1\", snapshot_digest=\"d1\",\n    )\n    assert client.posts == 1\n    assert result[\"status\"] == \"provider_state_uncertain\"\n    assert result[\"provider_write_reached\"] is True\n    assert result[\"requested_change\"] == {\"daily_budget\": \"11000\"}\n    assert result[\"uncertainty_reason\"] == \"meta_verification_read_failed\"\n\n\n@pytest.mark.asyncio\nasync def test_p0_4_post_transport_exception_is_never_classified_failed_safe_to_retry(monkeypatch):\n    client = _Client(\n        gets=[_Response(200, {\"status\": \"ACTIVE\", \"daily_budget\": \"10000\"})],\n        post=TimeoutError(\"outcome unknown\"),\n    )\n    await _prepare_meta_test(monkeypatch, client)\n    result = await legacy._execute_meta_approval(\n        object(), \"u1\",\n        {\"action\": \"scale\", \"entity_level\": \"campaign\", \"change_percent\": 10},\n        {\"entity_id\": \"c1\"},\n        snapshot_id=\"s1\", recommendation_id=\"r1\", snapshot_digest=\"d1\",\n    )\n    assert result[\"status\"] == \"provider_state_uncertain\"\n    assert result[\"provider_write_reached\"] is None\n    assert result[\"uncertainty_reason\"] == \"meta_write_transport_outcome_unknown\"\n\n\nclass _Collection:\n    def __init__(self, unresolved=None):\n        self.unresolved = unresolved\n        self.updates = []\n\n    async def find_one(self, *args, **kwargs):\n        return self.unresolved\n\n    async def update_one(self, query, update, **kwargs):\n        self.updates.append((query, update, kwargs))\n\n\nclass _DB(dict):\n    def __getitem__(self, key):\n        return dict.__getitem__(self, key)\n\n\n@pytest.mark.asyncio\nasync def test_p0_4_unresolved_prior_write_blocks_new_meta_mutation():\n    executions = _Collection({\n        \"execution_id\": \"e1\", \"snapshot_id\": \"s0\", \"recommendation_id\": \"r0\",\n        \"result\": {\"requested_change\": {\"daily_budget\": \"11000\"}},\n    })\n    db = _DB({legacy.EXECUTION_COLLECTION: executions, legacy.RECOMMENDATION_COLLECTION: _Collection()})\n    with pytest.raises(HTTPException) as caught:\n        await legacy._reconcile_meta_provider_uncertainty(\n            db, \"u1\", \"c1\", {\"status\": \"ACTIVE\", \"daily_budget\": \"10000\"}\n        )\n    assert caught.value.status_code == 409\n    assert caught.value.detail[\"code\"] == \"meta_provider_state_uncertain\"\n    assert executions.updates == []\n\n\n@pytest.mark.asyncio\nasync def test_p0_4_provider_confirmation_reconciles_old_execution():\n    executions = _Collection({\n        \"execution_id\": \"e1\", \"snapshot_id\": \"s0\", \"recommendation_id\": \"r0\",\n        \"result\": {\"requested_change\": {\"daily_budget\": \"11000\"}},\n    })\n    recommendations = _Collection()\n    db = _DB({legacy.EXECUTION_COLLECTION: executions, legacy.RECOMMENDATION_COLLECTION: recommendations})\n    resolved = await legacy._reconcile_meta_provider_uncertainty(\n        db, \"u1\", \"c1\", {\"status\": \"ACTIVE\", \"daily_budget\": \"11000\"}\n    )\n    assert resolved[\"resolved\"] is True\n    assert executions.updates[0][1][\"$set\"][\"status\"] == \"completed\"\n    assert recommendations.updates[0][1][\"$set\"][\"recommendations.$[item].execution_status\"] == \"completed\"\n'''


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        print(f"{label}: already patched")
        return text
    if old not in text:
        raise SystemExit(f"{label}: expected anchor not found")
    print(f"{label}: patched")
    return text.replace(old, new, 1)


def main() -> None:
    text = MONITOR.read_text(encoding="utf-8")
    if "def _meta_state_matches_mutation(" not in text:
        if INSERT_ANCHOR not in text:
            raise SystemExit("helper insertion anchor not found")
        text = text.replace(INSERT_ANCHOR, HELPERS + INSERT_ANCHOR, 1)
        print("meta uncertainty helpers: patched")
    else:
        print("meta uncertainty helpers: already patched")
    text = replace_once(text, OLD_META, NEW_META, "meta approval uncertainty flow")
    text = replace_once(text, STARTED_OLD, STARTED_NEW, "execution entity identity")
    text = replace_once(text, FINAL_OLD, FINAL_NEW, "execution final status")
    MONITOR.write_text(text, encoding="utf-8")
    TEST.write_text(TEST_CONTENT, encoding="utf-8")
    print(f"wrote {TEST.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
